                                                                                                                                                                                                            
  CREATE TABLE "CHECK_DEVICE_THIRD_PARTY_VALUE"                                                                                                                                                  
   (	"VALUE_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                        
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                                 
	"CREATION_DATE" DATE DEFAULT SYSDATE,                                                                                                                                                                      
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                                 
	"UPDATED_DATE" DATE,                                                                                                                                                                                       
	"TIME_POINT" NUMBER NOT NULL ENABLE,                                                                                                                                                                       
	"START_TIME" DATE NOT NULL ENABLE,                                                                                                                                                                         
	"END_TIME" DATE NOT NULL ENABLE,                                                                                                                                                                           
	"DEVICE_CODE" NVARCHAR2(100) NOT NULL ENABLE,                                                                                                                                                              
	"DATE_FORMAT" NVARCHAR2(32) NOT NULL ENABLE,                                                                                                                                                               
	"VALUE" NUMBER(10,6) NOT NULL ENABLE,                                                                                                                                                                      
	"FAB_ID" NUMBER NOT NULL ENABLE,                                                                                                                                                                           
	"LINE_ID" NUMBER NOT NULL ENABLE,                                                                                                                                                                          
	"AREA_ID" NUMBER NOT NULL ENABLE,                                                                                                                                                                          
	"DATA_TYPE" NVARCHAR2(32) DEFAULT 'EFFICIENCY' NOT NULL ENABLE,                                                                                                                                            
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                              
	"STATUS" NVARCHAR2(10) DEFAULT 'NORMAL' NOT NULL ENABLE,                                                                                                                                                   
	"RETRY_TIMES" NUMBER(*,0) DEFAULT 0,                                                                                                                                                                       
	 PRIMARY KEY ("VALUE_ID")                                                                                                                                                                                  
  USING INDEX  ENABLE,                                                                                                                                                                                      
	 CHECK ( STATUS in ('NORMAL', 'ABNORMAL') ) ENABLE                                                                                                                                                         
   ) ;                                                                                                                                                                                                      

